import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735:
# packet.NetworkSettings{CompressionThreshold: 1024, CompressionAlgorithm: packet.CompressionAlgorithmSnappy,
# ClientThrottle: true, ClientThrottleThreshold: 200, ClientThrottleScalar: 0.5}
SNAPPY = bytes.fromhex("0004010001c80000003f")

# generated by gophertunnel b8bd735:
# packet.NetworkSettings{CompressionAlgorithm: packet.CompressionAlgorithmNone}
NONE = bytes.fromhex("0000ffff000000000000")

GOLDENS = [
    *[
        pytest.param(
            version.NetworkSettingsPacket(
                compression_threshold=1024,
                compression_algorithm=version.PacketCompressionAlgorithm.SNAPPY,
                client_throttle_enabled=True,
                client_throttle_threshold=200,
                client_throttle_scalar=0.5,
            ),
            SNAPPY,
            id=f"{version.__name__.removeprefix('bedrock_protocol.')}-snappy",
        )
        for version in VERSIONS
    ],
    *[
        pytest.param(
            version.NetworkSettingsPacket(compression_algorithm=version.PacketCompressionAlgorithm.NONE),
            NONE,
            id=f"{version.__name__.removeprefix('bedrock_protocol.')}-no-compression",
        )
        for version in VERSIONS
    ],
]


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_network_settings_is_packet_143(version):
    assert version.PACKETS[143] is version.NetworkSettingsPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_network_settings_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_network_settings_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
